int ret = 0;
int res;
unsigned char *public = OPENSSL_hexstr2buf("7d4d0e7f6153a69b6242b522abbee685fda4420f8834b108c3bdae369ef549fa", NULL);
unsigned char *msg = OPENSSL_hexstr2buf("54657374", NULL);

size_t sig_len;
unsigned char *sigg = NULL;

EVP_PKEY *pkey = EVP_PKEY_new_raw_public_key(NID_ED25519, NULL, public, 32);
assert(pkey != NULL);
EVP_MD_CTX *ctx = EVP_MD_CTX_new();
res = EVP_DigestSignInit(ctx, NULL, NULL, NULL, pkey);
assert(res == 1);

if (EVP_DigestSign(ctx, NULL, &sig_len, msg, 4) != 1)
   printf("EVP_DigestSign get the size of signature buffer fail\n");
sigg = OPENSSL_zalloc(sig_len);
if (EVP_DigestSign(ctx, sigg, &sig_len, msg, 4) != 1)
   printf("EVP_DigestSign fail\n");

printf("ok\n");
exit(ret);

